import { randomUUID } from "node:crypto";
import { Pool, PoolClient } from "pg";
import {
  appendInvestigationContext,
  InvestigationEvent,
  InvestigationTarget,
  investigateIssues,
} from "./claims.js";
import { decideClaimPaths } from "./decisions.js";
import { executeEligiblePayments, hasUnresolvedPaySwiftPayment, reconcilePaySwiftLedger } from "./payments.js";
import { PaySwiftClient } from "../infrastructure/payswift/client.js";
import {
  GroqMessageUnderstander,
  IssueUpdate,
  LanguageUnderstandingUnavailable,
  MessageUnderstanding,
  RecentMessage,
  sanitizeUnderstanding,
} from "../infrastructure/llm/groq-client.js";

export class MessageIdConflict extends Error {}
export class StoredMessageUnavailable extends Error {}
export class MessageUnderstandingUnavailable extends Error {}

interface StoredInboundMessage {
  rider_id: string;
  text: string;
  received_at: Date;
  reply: string | null;
  processing_status: string;
}

export async function receiveMessage(
  pool: Pool,
  understander: GroqMessageUnderstander,
  args: { messageId: string; riderId: string; text: string; receivedAt: Date },
  paySwift: PaySwiftClient = new PaySwiftClient(),
): Promise<string> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const inserted = await client.query(
      `INSERT INTO inbound_messages (message_id, rider_id, text, received_at, reply, processing_status)
       VALUES ($1, $2, $3, $4, NULL, 'processing')
       ON CONFLICT (message_id) DO NOTHING RETURNING message_id`,
      [args.messageId, args.riderId, args.text, args.receivedAt],
    );

    if (inserted.rowCount === 0) {
      const existing = await client.query<StoredInboundMessage>(
        `SELECT rider_id, text, received_at, reply, processing_status
         FROM inbound_messages WHERE message_id = $1 FOR UPDATE`,
        [args.messageId],
      );
      const stored = existing.rows[0];
      if (!stored) throw new StoredMessageUnavailable("A duplicate message could not be loaded.");
      if (stored.rider_id !== args.riderId || stored.text !== args.text || stored.received_at.getTime() !== args.receivedAt.getTime()) {
        throw new MessageIdConflict("message_id has already been used for different message content.");
      }
      if (stored.processing_status === "processed" && stored.reply !== null) {
        await client.query("COMMIT");
        return stored.reply;
      }
      if (stored.processing_status === "processing") {
        throw new StoredMessageUnavailable("The earlier copy of this message is still being processed.");
      }
      await client.query(
        `UPDATE inbound_messages SET processing_status = 'processing', reply = NULL WHERE message_id = $1`,
        [args.messageId],
      );
    } else {
      await addTrace(client, args.riderId, "message_in", "inbound_message", {
        message_id: args.messageId,
        text: args.text,
        received_at: args.receivedAt.toISOString(),
      }, null);
    }
    await client.query("COMMIT");
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally {
    client.release();
  }

  try {
    const { state, recentMessages } = await loadContext(pool, args.riderId, args.messageId);
    let ledgerAvailable = true;
    let ledgerEvents: InvestigationEvent[] = [];
    let reconciliationAttempted = false;
    if (await hasUnresolvedPaySwiftPayment(pool, args.riderId)) {
      reconciliationAttempted = true;
      try {
        const reconciliation = await reconcilePaySwiftLedger(pool, args.riderId, paySwift);
        ledgerEvents = reconciliation.events;
      } catch (error) {
        ledgerAvailable = false;
        ledgerEvents = [{
          type: "error",
          name: "payswift_ledger_reconciliation_failed",
          input: { rider_id: args.riderId, reason: "unresolved_payment_follow_up" },
          output: { error: error instanceof Error ? error.message : "unknown PaySwift ledger error", payment_blocked: true },
        }];
      }
      if (ledgerEvents.some((event) => event.type === "error")) await persistEvents(pool, args.riderId, ledgerEvents);
    }
    const modelResult = await understander.understand({
      riderId: args.riderId,
      text: args.text,
      receivedAt: args.receivedAt,
      existingIssues: modelIssueContext(state.issues),
      recentMessages,
    });
    const result = sanitizeUnderstanding(modelResult, {
      text: args.text,
      riderId: args.riderId,
      receivedAt: args.receivedAt,
      existingIssues: state.issues,
    });
    await addTraceToPool(pool, args.riderId, "model", "groq_message_understanding", {
      message_id: args.messageId,
      active_issue_ids: state.issues.map((issue) => issue.issue_id ?? null),
    }, result);
    const applied = applyUpdates(state, result, args.messageId, args.receivedAt);
    const investigation = await investigateIssues(pool, args.riderId, args.receivedAt, applied.targets);
    await persistEvents(pool, args.riderId, investigation.events);
    const verifiedClaimsExist = investigation.outcomes.some((item) => item.status === "verified_shortfall");
    if (verifiedClaimsExist && !reconciliationAttempted) {
      reconciliationAttempted = true;
      try {
        const reconciliation = await reconcilePaySwiftLedger(pool, args.riderId, paySwift);
        ledgerEvents.push(...reconciliation.events);
      } catch (error) {
        ledgerAvailable = false;
        ledgerEvents = [{
          type: "error",
          name: "payswift_ledger_reconciliation_failed",
          input: { rider_id: args.riderId },
          output: { error: error instanceof Error ? error.message : "unknown PaySwift ledger error", payment_blocked: true },
        }];
      }
      if (ledgerEvents.some((event) => event.type === "error")) await persistEvents(pool, args.riderId, ledgerEvents);
    }
    const decisions = await decideClaimPaths(pool, args.riderId, investigation.outcomes, {
      messageId: args.messageId,
      identityMismatch: result.identity_mismatch,
      paymentProviderAvailable: ledgerAvailable,
    });
    await persistEvents(pool, args.riderId, decisions.events);
    const payments = await executeEligiblePayments(pool, args.riderId, decisions.outcomes, paySwift);
    await persistEvents(pool, args.riderId, payments.events);
    const updatedState = appendInvestigationContext(applied.state, decisions.outcomes);
    const reply = decisions.identityMismatchReply ?? (decisions.outcomes.length > 0
      ? decisions.outcomes.map((item) => item.reply).join(" ")
      : result.reply);
    await saveCompletedMessage(pool, args, reply, updatedState);
    return reply;
  } catch (error) {
    await markFailed(pool, args.messageId, args.riderId,
      error instanceof LanguageUnderstandingUnavailable ? "language_understanding_unavailable" : "message_processing_failed");
    if (error instanceof LanguageUnderstandingUnavailable) {
      throw new MessageUnderstandingUnavailable("Message understanding is temporarily unavailable.", { cause: error });
    }
    throw error;
  }
}

interface ConversationState {
  issues: Record<string, unknown>[];
  [key: string]: unknown;
}

async function loadContext(pool: Pool, riderId: string, currentMessageId: string): Promise<{
  state: ConversationState;
  recentMessages: RecentMessage[];
}> {
  const [conversation, history] = await Promise.all([
    pool.query<{ state: unknown }>("SELECT state FROM conversations WHERE rider_id = $1", [riderId]),
    pool.query<{ received_at: Date; text: string; reply: string | null }>(
      `SELECT received_at, text, reply FROM inbound_messages
       WHERE rider_id = $1 AND message_id <> $2 AND processing_status = 'processed'
       ORDER BY received_at DESC, message_id DESC LIMIT 8`,
      [riderId, currentMessageId],
    ),
  ]);
  const rawState = conversation.rows[0]?.state;
  const stateObject = rawState && typeof rawState === "object" && !Array.isArray(rawState)
    ? rawState as Record<string, unknown> : {};
  const rawIssues = Array.isArray(stateObject.issues) ? stateObject.issues : [];
  return {
    state: { ...stateObject, issues: rawIssues.filter(isJsonObject) },
    recentMessages: history.rows.reverse().map((row) => ({
      received_at: row.received_at.toISOString(),
      rider_message: row.text,
      // Replies may contain deterministic payout amounts; keep them out of Groq context.
      agent_reply: "",
    })),
  };
}

function isJsonObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function modelIssueContext(issues: Record<string, unknown>[]): Record<string, unknown>[] {
  const allowed = [
    "issue_id", "issue_type", "summary", "trip_ids", "dates",
    "missing_information", "follow_up_question",
  ];
  return issues.map((issue) => Object.fromEntries(
    allowed.filter((key) => key in issue).map((key) => [key, issue[key]]),
  ));
}

function applyUpdates(
  state: ConversationState,
  result: MessageUnderstanding,
  messageId: string,
  receivedAt: Date,
): { state: ConversationState; targets: InvestigationTarget[] } {
  const issues = [...state.issues];
  const targets: InvestigationTarget[] = [];
  if (!result.identity_mismatch) {
    for (const update of result.updates) {
      const issue = issueState(update, receivedAt);
      if (update.action === "create" && update.issue_id === null) {
        const issueId = randomUUID();
        issues.push({ issue_id: issueId, ...issue });
        targets.push({ issueId, update });
      } else if (update.action === "update" && update.issue_id) {
        const index = issues.findIndex((existing) => existing.issue_id === update.issue_id);
        if (index >= 0) {
          issues[index] = { issue_id: update.issue_id, ...issue };
          targets.push({ issueId: update.issue_id, update });
        }
      }
    }
  }
  return {
    state: { ...state, issues, last_message_id: messageId, updated_at: receivedAt.toISOString() },
    targets,
  };
}

function issueState(update: IssueUpdate, receivedAt: Date): Record<string, unknown> {
  return {
    issue_type: update.issue_type,
    summary: update.summary,
    trip_ids: update.trip_ids,
    dates: update.dates,
    missing_information: update.missing_information,
    follow_up_question: update.follow_up_question,
    updated_at: receivedAt.toISOString(),
  };
}

async function saveCompletedMessage(
  pool: Pool,
  args: { messageId: string; riderId: string },
  reply: string,
  updatedState: ConversationState,
): Promise<void> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await client.query(
      `INSERT INTO conversations (rider_id, state) VALUES ($1, $2::jsonb)
       ON CONFLICT (rider_id) DO UPDATE SET state = EXCLUDED.state, updated_at = now()`,
      [args.riderId, JSON.stringify(updatedState)],
    );
    await client.query(
      `UPDATE inbound_messages SET reply = $2, processing_status = 'processed' WHERE message_id = $1`,
      [args.messageId, reply],
    );
    await addTrace(client, args.riderId, "decision", "conversation_context_updated", {
      message_id: args.messageId,
    }, updatedState);
    await addTrace(client, args.riderId, "reply", "rider_follow_up", null, reply);
    await client.query("COMMIT");
  } catch (error) {
    if (update.missing_information.includes("issue_details")) return "Could you describe what seems wrong with the payout?";
  }
  return "I have noted the details you shared. Is there anything else about this payout issue?";
}

function containsUnsafeReply(reply: string): boolean {
  if (unsafeReplyPattern.test(reply)) return true;
  return /\d/.test(reply.replace(tripTokenPattern, ""));
}

export function sanitizeUnderstanding(
  result: MessageUnderstanding,
  args: { text: string; riderId: string; receivedAt: Date; existingIssues?: Record<string, unknown>[] },
): MessageUnderstanding {
  if (result.identity_mismatch || referencesAnotherRider(args.text, args.riderId)) {
    return {
      updates: [],
      identity_mismatch: true,
      reply: "I can help only with the rider account linked to this number. Please describe an issue with your own account.",
    };
  }

  const latestDate = istDate(args.receivedAt);
  const countCorrection = /\b\d+\s*(?:kiye(?:\s+the)?|kiya(?:\s+tha|\s+the)?|trips?\s+(?:kiye|completed))\b/i.test(args.text);
  const relativeDay = /\b(\d{1,2})\s*(?:wala|wali|waale|tarikh| तारीख)\b/i.exec(args.text)?.[1];
  const inheritedIssue = (update: IssueUpdate) => args.existingIssues?.find((issue) => issue.issue_id === update.issue_id);
  const updates = result.updates.map((update) => {
    let dates = [...new Set(update.dates.filter((date) => isValidDateOnly(date) && date <= latestDate))];
    const prior = inheritedIssue(update);
    const priorDates = Array.isArray(prior?.dates) ? prior.dates.filter((date): date is string => typeof date === "string" && isValidDateOnly(date)) : [];
    // A numeric trip count in a correction must not replace the issue's date.
    if (countCorrection && priorDates.length > 0) dates = priorDates;
    // Resolve concise answers like "20 wala" against the active issue month.
    if (relativeDay && !dates.length) {
      const day = Number(relativeDay);
      const [year, month] = latestDate.split("-").map(Number);
      const candidate = `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
      if (isValidDateOnly(candidate) && candidate <= latestDate) dates = [candidate];
    }
    return {
      ...update,
      trip_ids: [...new Set(update.trip_ids.map((id) => id.trim().toUpperCase()).filter((id) => tripIdPattern.test(id)))],
      dates,
      missing_information: update.missing_information.filter((field) => !(dates.length && field === "date")),
      follow_up_question: update.follow_up_question && !unsafeReplyPattern.test(update.follow_up_question)
        ? update.follow_up_question : null,
    };
  });

  let reply = result.reply.trim();
  if (!reply || containsUnsafeReply(reply)) reply = safeFallback(updates);
  const needsFollowUp = updates.some((update) => update.missing_information.length > 0);
  if (needsFollowUp && !/[?؟]$/.test(reply)) {
    const question = [...updates].reverse().find((update) => update.follow_up_question)?.follow_up_question;
    reply = question ? `${reply.replace(/[.!\s]+$/, "")} ${question}` : safeFallback(updates);
  }
  return { updates, identity_mismatch: false, reply: reply.slice(0, 1000) };
}

function istDateTime(value: Date): string {
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: "Asia/Kolkata",
    year: "numeric", month: "2-digit", day: "2-digit",
    hour: "2-digit", minute: "2-digit", second: "2-digit", hourCycle: "h23",
  }).formatToParts(value);
  const field = (type: string) => parts.find((part) => part.type === type)?.value ?? "00";
  return `${field("year")}-${field("month")}-${field("day")}T${field("hour")}:${field("minute")}:${field("second")}+05:30`;
}

function isValidDateOnly(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const parsed = new Date(`${value}T00:00:00.000Z`);
  return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
}
#!/usr/bin/env python3
"""Black-box conversation evaluator. It calls only the service and PaySwift HTTP APIs."""

from __future__ import annotations

import json
import sys
import time
import uuid
from datetime import datetime, timezone
from typing import Any
from urllib.error import HTTPError, URLError
from urllib.parse import urlparse
from urllib.request import Request, urlopen
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
CONVERSATIONS = ROOT / "data" / "conversations.json"


class EvalError(RuntimeError):
    pass


def request_json(url: str, method: str = "GET", body: Any = None, timeout: float = 20) -> Any:
    data = json.dumps(body).encode() if body is not None else None
    request = Request(url, data=data, method=method, headers={"Content-Type": "application/json"})
    for attempt in range(2):
        try:
            with urlopen(request, timeout=timeout) as response:
                return json.loads(response.read().decode())
        except HTTPError as exc:
            text = exc.read().decode(errors="replace")
            if exc.code in {429, 503} and attempt == 0:
                # /messages is idempotent by message_id, so retrying the same
                # request is safe after temporary provider throttling.
                retry_after = exc.headers.get("Retry-After")
                try:
                    delay = float(retry_after) if retry_after else 12.0
                except ValueError:
                    delay = 12.0
                time.sleep(min(max(delay, 1.0), 30.0))
                continue
            raise EvalError(f"HTTP {exc.code} from {url}: {text[:400]}") from exc
        except (URLError, TimeoutError) as exc:
            raise EvalError(f"Could not reach {url}: {exc}") from exc
    raise EvalError(f"Retry budget exhausted for {url}")


def payouts_for(base: str, rider_id: str) -> list[dict[str, Any]]:
    from urllib.parse import quote
    result = request_json(f"{base}/v1/payouts?rider_id={quote(rider_id)}")
    if isinstance(result, list):
        return result
    if isinstance(result, dict):
        rows = result.get("data", result.get("payouts"))
        if isinstance(rows, list):
            return rows
    raise EvalError("PaySwift ledger response did not contain a payout list")


def amounts_by_id(rows: list[dict[str, Any]]) -> dict[str, int]:
    return {str(row.get("payout_id", row.get("id", ""))): int(row.get("amount", row.get("amount_rupees", 0))) for row in rows}


def new_ops(base: str, rider_id: str, before: set[str]) -> list[dict[str, Any]]:
    rows = request_json(f"{base}/ops/pending")
    if not isinstance(rows, list):
        raise EvalError("/ops/pending did not return a JSON list")
    return [row for row in rows if row.get("rider_id") == rider_id and str(row.get("id")) not in before]


def fresh_id(scenario_id: str, source: str) -> str:
    return f"eval-{scenario_id}-{source}-{uuid.uuid4().hex[:8]}"


def expected_options(expected: dict[str, Any]) -> list[dict[str, Any]]:
    return expected.get("one_of") or [expected]


def run_case(index: int, case: dict[str, Any], api: str, payswift: str) -> dict[str, Any]:
    scenario_id = f"{index:02d}-{uuid.uuid4().hex[:6]}"
    rider = case["rider_id"]
    before_payouts = amounts_by_id(payouts_for(payswift, rider))
    pending = request_json(f"{api}/ops/pending")
    before_ops = {str(row.get("id")) for row in pending if row.get("rider_id") == rider}
    replies: list[str] = []
    replies_by_source_id: dict[str, str] = {}
    message_ids: dict[str, str] = {}
    duplicate_ok = True
    trace: list[dict[str, Any]] = []
    error: str | None = None

    try:
        for turn in case.get("turns", []):
            if turn.get("from") != "rider":
                continue
            original_id = str(turn["message_id"])
            message_id = message_ids.setdefault(original_id, fresh_id(scenario_id, original_id[-8:]))
            payload = {"message_id": message_id, "rider_id": rider, "text": turn["text"], "received_at": turn["received_at"]}
            response = request_json(f"{api}/messages", "POST", payload, timeout=45)
            reply = str(response.get("reply", ""))
            if not reply:
                raise EvalError(f"message {original_id} returned no reply")
            replies.append(reply)
            replies_by_source_id.setdefault(original_id, reply)
        # Replay each repeated source message exactly as delivered, to verify saved-reply idempotency.
        seen: set[str] = set()
        for turn in case.get("turns", []):
            if turn.get("from") != "rider":
                continue
            original_id = str(turn["message_id"])
            if original_id in seen:
                payload = {"message_id": message_ids[original_id], "rider_id": rider, "text": turn["text"], "received_at": turn["received_at"]}
                replay = request_json(f"{api}/messages", "POST", payload, timeout=45)
                duplicate_ok = str(replay.get("reply", "")) == replies_by_source_id[original_id]
            seen.add(original_id)
    except (EvalError, KeyError, TypeError, ValueError) as exc:
        error = str(exc)

    created_payouts: dict[str, int] = {}
    created_ops: list[dict[str, Any]] = []
    try:
        after_payouts = amounts_by_id(payouts_for(payswift, rider))
        created_payouts = {key: amount for key, amount in after_payouts.items() if key not in before_payouts}
        created_ops = new_ops(api, rider, before_ops)
        trace = request_json(f"{api}/trace/{rider}")
    except (EvalError, KeyError, TypeError, ValueError) as exc:
        error = f"{error}; unable to collect final observations: {exc}" if error else str(exc)
        trace = []

    payout_amount = sum(created_payouts.values())
    approval_amount = sum(int(row.get("amount") or 0) for row in created_ops if row.get("type") == "approval")
    escalation_count = sum(1 for row in created_ops if row.get("type") == "escalation")
    reply_text = "\n".join(replies).lower()
    mentions = case.get("expected", {}).get("reply_mentions", [])
    mention_failures = [str(word) for word in mentions if str(word).lower() not in reply_text]
    trace_times = [str(event.get("at", "")) for event in trace if event.get("at")]
    trace_ordered = trace_times == sorted(trace_times)
    observed = {"payout": payout_amount, "approval": approval_amount or None, "escalations": escalation_count,
                "new_payouts": created_payouts, "new_ops_ids": [row.get("id") for row in created_ops],
                "duplicate_replay_same_reply": duplicate_ok, "trace_ordered": trace_ordered}
    failures: list[str] = []
    if error:
        failures.append(error)
    expected = case.get("expected", {})
    accepted = False
    for option in expected_options(expected):
        if option.get("payout", 0) != payout_amount:
            continue
        if option.get("approval") != (approval_amount or None):
            continue
        accepted = True
        break
    if not accepted:
        failures.append(f"expected one of {expected_options(expected)}; observed payout={payout_amount}, approval={approval_amount or None}")
    escalation_rule = expected.get("escalation", "optional")
    if escalation_rule == "no" and escalation_count:
        failures.append(f"unexpected {escalation_count} escalation(s)")
    if escalation_rule == "required" and not escalation_count:
        failures.append("expected an escalation, but none was created")
    if mention_failures:
        failures.append(f"reply omitted expected text: {mention_failures}")
    if not duplicate_ok:
        failures.append("duplicate message did not return the same saved reply")
    if not trace_ordered:
        failures.append("trace timestamps are not chronological")
    return {"scenario": case.get("scenario", f"case {index}"), "rider_id": rider,
            "status": "PASS" if not failures else "FAIL", "observed": observed,
            "replies": replies, "failures": failures}


def main() -> int:
    if len(sys.argv) not in {2, 4} or (len(sys.argv) == 4 and sys.argv[2] != "--case"):
        print("Usage: python3 evals/run.py <service-url> [--case 1-24]", file=sys.stderr)
        return 2
    api = sys.argv[1].rstrip("/")
    parsed = urlparse(api)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        print("Service URL must include http:// or https://", file=sys.stderr)
        return 2
    payswift = f"{parsed.scheme}://{parsed.hostname}:8081"
    try:
        request_json(f"{api}/health")
        request_json(f"{payswift}/health")
    except EvalError as exc:
        print(f"Evaluator could not start: {exc}", file=sys.stderr)
        return 2
    cases = json.loads(CONVERSATIONS.read_text())
    if not isinstance(cases, list) or len(cases) != 24:
        print(f"Expected 24 supplied conversations, found {len(cases) if isinstance(cases, list) else 'invalid data'}", file=sys.stderr)
        return 2
    if len(sys.argv) == 4:
        try:
            case_number = int(sys.argv[3])
        except ValueError:
            print("--case must be an integer from 1 to 24", file=sys.stderr)
            return 2
        if case_number < 1 or case_number > len(cases):
            print("--case must be an integer from 1 to 24", file=sys.stderr)
            return 2
        selected_cases = [(case_number, cases[case_number - 1])]
    else:
        selected_cases = list(enumerate(cases, 1))
    results = []
    for case_index, (index, case) in enumerate(selected_cases):
        if case_index:
            time.sleep(15)
        results.append(run_case(index, case, api, payswift))
    passed = sum(row["status"] == "PASS" for row in results)
    print(f"\nEvaluation: {passed}/{len(results)} passed; {len(results)-passed} failed")
    for index, row in enumerate(results, 1):
        observed = row["observed"]
        result = f"{index:02d} {row['status']} | {row['rider_id']} | payout ₹{observed['payout']} | approval {observed['approval']} | escalations {observed['escalations']} | {row['scenario']}"
        print(result)
        for failure in row["failures"]:
            print(f"   - {failure}")
    report_path = Path("eval-results.json")
    report_path.write_text(json.dumps({
        "run_at": datetime.now(timezone.utc).isoformat(),
        "service_url": api,
        "fresh_service_required_per_conversation": True,
        "case_numbers": [index for index, _ in selected_cases],
        "case_cooldown_seconds": 15,
        "passed": passed,
        "total": len(results),
        "results": results,
    }, ensure_ascii=False, indent=2) + "\n")
    print(f"\nFull JSON report: {report_path.resolve()}")
    return 0 if passed == len(results) else 1


if __name__ == "__main__":
    raise SystemExit(main())
