    // Groq can reply 429 when the organization's token window is full. Leave a
    // small SDK retry budget enabled so it can honor Retry-After and back off.
    this.client = apiKey ? new Groq({ apiKey, timeout: timeoutSeconds * 1000, maxRetries: 2 }) : null;
  }

