        model: this.model,
        messages: [
          { role: "system" as const, content: instructions },
          { role: "user" as const, content: JSON.stringify(payload) },
        ],
        temperature: 0,
        // The extraction JSON is small; a lower ceiling reduces token pressure
        // and leaves more room under organization-level TPM limits.
        max_completion_tokens: 1200,
      };
      let response;
      try {
        response = await this.client.chat.completions.create({
          ...request,
          response_format: {
          type: "json_schema",
          json_schema: {
            name: "rider_message_understanding",
            strict: true,
            schema: outputSchema,
          },
          },
        });
      } catch (error) {
        if (!isJsonValidationFailure(error)) throw error;
        // Groq can occasionally reject a structured generation before returning
        // content. Retry with JSON syntax mode, then enforce the same Zod schema
        // locally before any decision code receives the result.
        failureStage = "json_object_fallback";
        response = await this.client.chat.completions.create({
          ...request,
          response_format: { type: "json_object" },
        });
      }
      failureStage = "response_received";
      const choice = response.choices[0];
      const content = choice?.message.content;
      completionMetadata = {
        choice_count: response.choices.length,
        finish_reason: choice?.finish_reason,
        content_present: Boolean(content),
        content_length: typeof content === "string" ? content.length : 0,
      };
      if (!content) {
        failureStage = "empty_response";
        throw new Error("Groq returned an empty response");
      }
      failureStage = "json_parse";
      const parsed = JSON.parse(content);
      failureStage = "schema_validation";
      return messageUnderstandingSchema.parse(parsed);
    } catch (error) {
      // Keep the public response generic, but leave enough provider metadata in
      // the app logs to diagnose configuration/model/API failures. Never log
      // the API key, request payload, rider text, or full provider message.
      const details = error && typeof error === "object"
        ? error as {
          status?: unknown;
          code?: unknown;
          type?: unknown;
          requestID?: unknown;
          request_id?: unknown;
          cause?: unknown;
          error?: unknown;
        }
        : {};
      const cause = details.cause && typeof details.cause === "object"
        ? details.cause as { name?: unknown; code?: unknown }
        : {};
      const providerError = details.error && typeof details.error === "object"
        ? details.error as { code?: unknown; type?: unknown }
        : {};
      let errorSummary = error instanceof Error ? error.message : typeof error;
      const privateText = [
        process.env.GROQ_API_KEY,
        args.text,
        ...args.recentMessages.flatMap((message) => [message.rider_message, message.agent_reply]),
      ].filter((value): value is string => typeof value === "string" && value.length >= 3);
      for (const value of privateText) errorSummary = errorSummary.split(value).join("[redacted]");
      errorSummary = errorSummary
        .replace(/gsk_[A-Za-z0-9_-]+/g, "[redacted-key]")
        .replace(/Bearer\s+\S+/gi, "Bearer [redacted]")
        .slice(0, 240);
      console.error("Groq message understanding request failed", {
        failure_stage: failureStage,
        error_name: error instanceof Error ? error.name : typeof error,
        error_summary: errorSummary,
        status: typeof details.status === "number" ? details.status : undefined,
        code: typeof details.code === "string" ? details.code : providerError.code,
        type: typeof details.type === "string" ? details.type : providerError.type,
        request_id: typeof details.requestID === "string"
          ? details.requestID
          : typeof details.request_id === "string" ? details.request_id : undefined,
        cause_name: typeof cause.name === "string" ? cause.name : undefined,
        cause_code: typeof cause.code === "string" ? cause.code : undefined,
        validation_issues: error instanceof z.ZodError
          ? error.issues.map((issue) => ({ code: issue.code, path: issue.path }))
          : undefined,
        completion: completionMetadata,
      });
      throw new LanguageUnderstandingUnavailable("Groq could not understand the rider message.", { cause: error });
    }
  }
}

function isJsonValidationFailure(error: unknown): boolean {
  if (!error || typeof error !== "object") return false;
  const details = error as { status?: unknown; code?: unknown; message?: unknown; error?: unknown };
  const nested = details.error && typeof details.error === "object"
    ? details.error as { code?: unknown }
    : {};
  return details.status === 400 && (
    details.code === "json_validate_failed" ||
    nested.code === "json_validate_failed" ||
    (typeof details.message === "string" && details.message.includes("json_validate_failed"))
  );
}

function normalizeRiderId(value: string): string {
  const match = /^R(\d+)$/i.exec(value.trim());
  return match ? `R${Number(match[1]).toString().padStart(3, "0")}` : value.trim().toUpperCase();
}

function referencesAnotherRider(text: string, riderId: string): boolean {
  const boundId = normalizeRiderId(riderId);
  return [...text.matchAll(riderIdPattern)].some(([match]) => normalizeRiderId(match) !== boundId);
}

function safeFallback(updates: IssueUpdate[]): string {
  for (const update of [...updates].reverse()) {
    if (update.missing_information.includes("date") && update.missing_information.includes("trip_id")) {
      return "Could you share the date or order ID related to the payout issue?";
    }
    if (update.missing_information.includes("date")) return "Which date's payout is the issue about?";
    if (update.missing_information.includes("trip_id")) return "Could you share the related order ID?";
import { randomUUID } from "node:crypto";
import { Pool, PoolClient } from "pg";
import {
  appendInvestigationContext,
  InvestigationEvent,
  InvestigationTarget,
  investigateIssues,
} from "./claims.js";
import { decideClaimPaths } from "./decisions.js";
import { executeEligiblePayments, hasUnresolvedPaySwiftPayment, reconcilePaySwiftLedger } from "./payments.js";
import { PaySwiftClient } from "../infrastructure/payswift/client.js";
import {
  GroqMessageUnderstander,
  IssueUpdate,
  LanguageUnderstandingUnavailable,
  MessageUnderstanding,
  RecentMessage,
  sanitizeUnderstanding,
} from "../infrastructure/llm/groq-client.js";

export class MessageIdConflict extends Error {}
export class StoredMessageUnavailable extends Error {}
export class MessageUnderstandingUnavailable extends Error {}

interface StoredInboundMessage {
  rider_id: string;
  text: string;
  received_at: Date;
  reply: string | null;
  processing_status: string;
}

export async function receiveMessage(
  pool: Pool,
  understander: GroqMessageUnderstander,
  args: { messageId: string; riderId: string; text: string; receivedAt: Date },
  paySwift: PaySwiftClient = new PaySwiftClient(),
): Promise<string> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const inserted = await client.query(
      `INSERT INTO inbound_messages (message_id, rider_id, text, received_at, reply, processing_status)
       VALUES ($1, $2, $3, $4, NULL, 'processing')
       ON CONFLICT (message_id) DO NOTHING RETURNING message_id`,
      [args.messageId, args.riderId, args.text, args.receivedAt],
    );

    if (inserted.rowCount === 0) {
      const existing = await client.query<StoredInboundMessage>(
        `SELECT rider_id, text, received_at, reply, processing_status
         FROM inbound_messages WHERE message_id = $1 FOR UPDATE`,
        [args.messageId],
      );
      const stored = existing.rows[0];
      if (!stored) throw new StoredMessageUnavailable("A duplicate message could not be loaded.");
      if (stored.rider_id !== args.riderId || stored.text !== args.text || stored.received_at.getTime() !== args.receivedAt.getTime()) {
        throw new MessageIdConflict("message_id has already been used for different message content.");
      }
      if (stored.processing_status === "processed" && stored.reply !== null) {
        await client.query("COMMIT");
        return stored.reply;
      }
      if (stored.processing_status === "processing") {
        throw new StoredMessageUnavailable("The earlier copy of this message is still being processed.");
      }
      await client.query(
        `UPDATE inbound_messages SET processing_status = 'processing', reply = NULL WHERE message_id = $1`,
        [args.messageId],
      );
    } else {
      await addTrace(client, args.riderId, "message_in", "inbound_message", {
        message_id: args.messageId,
        text: args.text,
        received_at: args.receivedAt.toISOString(),
      }, null);
    }
    await client.query("COMMIT");
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally {
    client.release();
  }

  try {
    const { state, recentMessages } = await loadContext(pool, args.riderId, args.messageId);
    let ledgerAvailable = true;
    let ledgerEvents: InvestigationEvent[] = [];
    let reconciliationAttempted = false;
    if (await hasUnresolvedPaySwiftPayment(pool, args.riderId)) {
      reconciliationAttempted = true;
      try {
        const reconciliation = await reconcilePaySwiftLedger(pool, args.riderId, paySwift);
        ledgerEvents = reconciliation.events;
      } catch (error) {
        ledgerAvailable = false;
        ledgerEvents = [{
          type: "error",
          name: "payswift_ledger_reconciliation_failed",
          input: { rider_id: args.riderId, reason: "unresolved_payment_follow_up" },
          output: { error: error instanceof Error ? error.message : "unknown PaySwift ledger error", payment_blocked: true },
        }];
      }
      if (ledgerEvents.some((event) => event.type === "error")) await persistEvents(pool, args.riderId, ledgerEvents);
    }
    const modelResult = await understander.understand({
      riderId: args.riderId,
      text: args.text,
      receivedAt: args.receivedAt,
      existingIssues: modelIssueContext(state.issues),
      recentMessages,
    });
    let result = sanitizeUnderstanding(modelResult, {
      text: args.text,
      riderId: args.riderId,
      receivedAt: args.receivedAt,
      existingIssues: state.issues,
    });
    const priorFollowUp = resolveExistingClaimFollowUp(args.text, state);
    if (priorFollowUp) {
      // A payment-status or approval reminder must not reopen the verified
      // claim and run its payment/approval decision path a second time.
      result = { ...result, updates: [], identity_mismatch: false, reply: priorFollowUp };
    }
    await addTraceToPool(pool, args.riderId, "model", "groq_message_understanding", {
      message_id: args.messageId,
      active_issue_ids: state.issues.map((issue) => issue.issue_id ?? null),
    }, result);
    const applied = applyUpdates(state, result, args.messageId, args.receivedAt);
    const investigation = await investigateIssues(pool, args.riderId, args.receivedAt, applied.targets);
    await persistEvents(pool, args.riderId, investigation.events);
    const verifiedClaimsExist = investigation.outcomes.some((item) => item.status === "verified_shortfall");
    if (verifiedClaimsExist && !reconciliationAttempted) {
      reconciliationAttempted = true;
      try {
        const reconciliation = await reconcilePaySwiftLedger(pool, args.riderId, paySwift);
        ledgerEvents.push(...reconciliation.events);
      } catch (error) {
        ledgerAvailable = false;
        ledgerEvents = [{
          type: "error",
          name: "payswift_ledger_reconciliation_failed",
          input: { rider_id: args.riderId },
          output: { error: error instanceof Error ? error.message : "unknown PaySwift ledger error", payment_blocked: true },
        }];
      }
      if (ledgerEvents.some((event) => event.type === "error")) await persistEvents(pool, args.riderId, ledgerEvents);
    }
    const decisions = await decideClaimPaths(pool, args.riderId, investigation.outcomes, {
      messageId: args.messageId,
      identityMismatch: result.identity_mismatch,
      paymentProviderAvailable: ledgerAvailable,
    });
    await persistEvents(pool, args.riderId, decisions.events);
    const payments = await executeEligiblePayments(pool, args.riderId, decisions.outcomes, paySwift);
    await persistEvents(pool, args.riderId, payments.events);
    const updatedState = appendInvestigationContext(applied.state, decisions.outcomes);
    const reply = decisions.identityMismatchReply ?? (decisions.outcomes.length > 0
      ? decisions.outcomes.map((item) => item.reply).join(" ")
      : result.reply);
    await saveCompletedMessage(pool, args, reply, updatedState);
    return reply;
  } catch (error) {
    await markFailed(pool, args.messageId, args.riderId,
      error instanceof LanguageUnderstandingUnavailable ? "language_understanding_unavailable" : "message_processing_failed");
    if (error instanceof LanguageUnderstandingUnavailable) {
      throw new MessageUnderstandingUnavailable("Message understanding is temporarily unavailable.", { cause: error });
    }
    throw error;
  }
}

interface ConversationState {
  issues: Record<string, unknown>[];
  [key: string]: unknown;
}

async function loadContext(pool: Pool, riderId: string, currentMessageId: string): Promise<{
  state: ConversationState;
  recentMessages: RecentMessage[];
}> {
  const [conversation, history] = await Promise.all([
    pool.query<{ state: unknown }>("SELECT state FROM conversations WHERE rider_id = $1", [riderId]),
    pool.query<{ received_at: Date; text: string; reply: string | null }>(
      `SELECT received_at, text, reply FROM inbound_messages
       WHERE rider_id = $1 AND message_id <> $2 AND processing_status = 'processed'
       ORDER BY received_at DESC, message_id DESC LIMIT 8`,
      [riderId, currentMessageId],
    ),
  ]);
  const rawState = conversation.rows[0]?.state;
  const stateObject = rawState && typeof rawState === "object" && !Array.isArray(rawState)
    ? rawState as Record<string, unknown> : {};
  const rawIssues = Array.isArray(stateObject.issues) ? stateObject.issues : [];
  return {
    state: { ...stateObject, issues: rawIssues.filter(isJsonObject) },
    recentMessages: history.rows.reverse().map((row) => ({
      received_at: row.received_at.toISOString(),
      rider_message: row.text,
      // Replies may contain deterministic payout amounts; keep them out of Groq context.
      agent_reply: "",
    })),
  };
}

function isJsonObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function modelIssueContext(issues: Record<string, unknown>[]): Record<string, unknown>[] {
  const allowed = [
    "issue_id", "issue_type", "summary", "trip_ids", "dates",
    "missing_information", "follow_up_question",
  ];
  return issues.map((issue) => Object.fromEntries(
    allowed.filter((key) => key in issue).map((key) => [key, issue[key]]),
  ));
}

function resolveExistingClaimFollowUp(text: string, state: ConversationState): string | null {
  const outcomes = Array.isArray(state.latest_investigations)
    ? state.latest_investigations.filter(isJsonObject)
    : [];
  const normalized = text.toLowerCase();
  const asksPaymentStatus = /\b(kab\s+tak|kab\s+aayega|kab\s+milega|when\s+(?:will|does)|payment\s+status|status\s+kya|aaya\s+nahi|aayega)\b/i.test(normalized);
  if (asksPaymentStatus) {
    const paid = [...outcomes].reverse().find((item) => item.decision_path === "payment_succeeded");
    if (paid && typeof paid.reply === "string") return paid.reply;
  }

  const requestedAmount = /(?:₹|rs\.?\s*)?(\d+)\s*(?:wala|wali|waala|waali)\b/i.exec(normalized)?.[1];
  if (!requestedAmount || !/\b(abhi|de\s+do|bhej|send|pay|approve|jaldi)\b/i.test(normalized)) return null;
  const pending = [...outcomes].reverse().find((item) =>
    Number(item.decision_amount_rupees) === Number(requestedAmount) &&
    ["large_claim_approval", "repeat_claim_approval", "daily_limit_approval", "payment_provider_unavailable", "payment_result_uncertain", "payment_failed_review"].includes(String(item.decision_path)));
  if (pending && typeof pending.reply === "string") return pending.reply;
  return null;
}

