function isJsonValidationFailure(error: unknown): boolean {
  if (!error || typeof error !== "object") return false;
  const details = error as { status?: unknown; code?: unknown; message?: unknown; error?: unknown };
  const nested = details.error && typeof details.error === "object"
    ? details.error as { code?: unknown }
    : {};
  return details.status === 400 && (
    details.code === "json_validate_failed" ||
    nested.code === "json_validate_failed" ||
    (typeof details.message === "string" && details.message.includes("json_validate_failed"))
  );
}

function normalizeRiderId(value: string): string {
  const match = /^R(\d+)$/i.exec(value.trim());
  return match ? `R${Number(match[1]).toString().padStart(3, "0")}` : value.trim().toUpperCase();
}

function referencesAnotherRider(text: string, riderId: string): boolean {
  const boundId = normalizeRiderId(riderId);
  return [...text.matchAll(riderIdPattern)].some(([match]) => normalizeRiderId(match) !== boundId);
}

function safeFallback(updates: IssueUpdate[]): string {
  for (const update of [...updates].reverse()) {
    if (update.missing_information.includes("date") && update.missing_information.includes("trip_id")) {
      return "Could you share the date or order ID related to the payout issue?";
    }
    if (update.missing_information.includes("date")) return "Which date's payout is the issue about?";
    if (update.missing_information.includes("trip_id")) return "Could you share the related order ID?";
    if (update.missing_information.includes("issue_details")) return "Could you describe what seems wrong with the payout?";
  }
  return "I have noted the details you shared. Is there anything else about this payout issue?";
}

function containsUnsafeReply(reply: string): boolean {
  if (unsafeReplyPattern.test(reply)) return true;
  return /\d/.test(reply.replace(tripTokenPattern, ""));
}

export function sanitizeUnderstanding(
  result: MessageUnderstanding,
  args: { text: string; riderId: string; receivedAt: Date; existingIssues?: Record<string, unknown>[] },
): MessageUnderstanding {
  if (result.identity_mismatch || referencesAnotherRider(args.text, args.riderId)) {
    return {
      updates: [],
      identity_mismatch: true,
      reply: "I can help only with the rider account linked to this number. Please describe an issue with your own account.",
    };
  }

  const latestDate = istDate(args.receivedAt);
  const countCorrection = /\b\d+\s*(?:kiye(?:\s+the)?|kiya(?:\s+tha|\s+the)?|trips?\s+(?:kiye|completed))\b/i.test(args.text);
  const relativeDay = /\b(\d{1,2})\s*(?:wala|wali|waale|tarikh| तारीख)\b/i.exec(args.text)?.[1];
  const inheritedIssue = (update: IssueUpdate) => args.existingIssues?.find((issue) => issue.issue_id === update.issue_id);
  let updates = result.updates.map((update) => {
    let dates = [...new Set(update.dates.filter((date) => isValidDateOnly(date) && date <= latestDate))];
    const prior = inheritedIssue(update);
    const priorDates = Array.isArray(prior?.dates) ? prior.dates.filter((date): date is string => typeof date === "string" && isValidDateOnly(date)) : [];
    // A numeric trip count in a correction must not replace the issue's date.
    if (countCorrection && priorDates.length > 0) dates = priorDates;
    // Resolve concise answers like "20 wala" against the active issue month.
    if (relativeDay && !dates.length) {
      const day = Number(relativeDay);
      const [year, month] = latestDate.split("-").map(Number);
      const candidate = `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
      if (isValidDateOnly(candidate) && candidate <= latestDate) dates = [candidate];
    }
    return {
      ...update,
      trip_ids: [...new Set(update.trip_ids.map((id) => id.trim().toUpperCase()).filter((id) => tripIdPattern.test(id)))],
      dates,
      missing_information: update.missing_information.filter((field) => !(dates.length && field === "date")),
      follow_up_question: update.follow_up_question && !unsafeReplyPattern.test(update.follow_up_question)
        ? update.follow_up_question : null,
    };
  });

  // A specific trip plus an amount and component complaint (e.g. "₹300 kam,
  // trip T... ka surge nahi mila") is one trip claim, not a second day claim.
  const hasTripReference = tripTokenPattern.test(args.text);
  tripTokenPattern.lastIndex = 0;
  const hasAmount = /(?:₹|\b(?:rs\.?|inr|rupees?|rupay|rupaye)\s*)\s*\d+|\b\d+\s*(?:rupees?|rupay|rupaye)\b/i.test(args.text);
  const hasTripScopedClaim = updates.some((update) => update.trip_ids.length > 0);
  if (hasTripReference && hasAmount && hasTripScopedClaim) {
    updates = updates.filter((update) => update.trip_ids.length > 0);
  }

  let reply = result.reply.trim();
  if (!reply || containsUnsafeReply(reply)) reply = safeFallback(updates);
  const needsFollowUp = updates.some((update) => update.missing_information.length > 0);
  if (needsFollowUp && !/[?؟]$/.test(reply)) {
    const question = [...updates].reverse().find((update) => update.follow_up_question)?.follow_up_question;
    reply = question ? `${reply.replace(/[.!\s]+$/, "")} ${question}` : safeFallback(updates);
  }
  return { updates, identity_mismatch: false, reply: reply.slice(0, 1000) };
}

function istDateTime(value: Date): string {
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: "Asia/Kolkata",
    year: "numeric", month: "2-digit", day: "2-digit",
    hour: "2-digit", minute: "2-digit", second: "2-digit", hourCycle: "h23",
  }).formatToParts(value);
  const field = (type: string) => parts.find((part) => part.type === type)?.value ?? "00";
  return `${field("year")}-${field("month")}-${field("day")}T${field("hour")}:${field("minute")}:${field("second")}+05:30`;
}

function isValidDateOnly(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const parsed = new Date(`${value}T00:00:00.000Z`);
  return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
}
import { createHash, randomUUID } from "node:crypto";
import { Pool } from "pg";
import { istDate } from "../domain/payouts.js";
import { ClaimOutcome } from "./claims.js";

const AUTO_PAYMENT_CAP_RUPEES = 200;
const ACTIVE_PAYMENT_STATUSES = ["reserved", "processing", "unknown", "succeeded", "paid", "processed", "completed", "success", "created", "pending"];
const SUCCEEDED_PAYMENT_STATUSES = ["succeeded", "paid", "processed", "completed", "success"];

export interface DecisionEvent {
  type: "tool_call" | "decision" | "error";
  name: string;
  input: unknown;
  output: unknown;
}

export interface DecisionResult {
  outcomes: ClaimOutcome[];
  events: DecisionEvent[];
  identityMismatchReply?: string;
}

function fingerprintFor(riderId: string, item: ClaimOutcome): string {
  const details = {
    rider_id: riderId,
    scope: item.scope,
    dates: [...new Set(item.assessments.map((assessment) => assessment.payoutDate))].sort(),
    trip_ids: [...new Set(item.assessments.flatMap((assessment) => assessment.tripId ? [assessment.tripId] : []))].sort(),
    unresolved_reason: item.assessments.length === 0 ? item.reason : null,
  };
  return createHash("sha256").update(JSON.stringify(details)).digest("hex");
}

function claimEvidence(item: ClaimOutcome, fingerprint: string): Record<string, unknown> {
  return {
    issue_id: item.issue_id,
    fingerprint,
    scope: item.scope,
    status: item.status,
    decision_path: item.decision_path,
    decision_reason: item.decision_reason,
    verified_owed_rupees: item.verified_owed_rupees ?? 0,
    decision_amount_rupees: item.decision_amount_rupees ?? null,
    assessments: item.assessments.map((assessment) => ({
      rider_id: assessment.riderId,
      scope: assessment.scope,
      trip_id: assessment.tripId,
      payout_date: assessment.payoutDate,
      expected_rupees: assessment.expectedRupees,
      historical_paid_rupees: assessment.historicalPaidRupees,
      shortfall_rupees: assessment.shortfallRupees,
      breakdown: assessment.breakdown,
    })),
  };
}

export async function createPendingOpsItem(
  pool: Pool,
  args: { riderId: string; type: "approval" | "escalation"; amount: number | null; reason: string; fingerprint: string | null; claim: Record<string, unknown> },
): Promise<{ id: string; created: boolean }> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    if (args.fingerprint) {
      await client.query("SELECT pg_advisory_xact_lock(hashtextextended($1, 0))", [`${args.riderId}:${args.fingerprint}`]);
      const existing = await client.query<{ id: string }>(
        `SELECT id FROM ops_items
         WHERE rider_id = $1 AND claim_fingerprint = $2 AND item_type = $3 AND status = 'pending'
         ORDER BY created_at ASC LIMIT 1`,
        [args.riderId, args.fingerprint, args.type],
      );
      if (existing.rows[0]) {
        await client.query("COMMIT");
        return { id: existing.rows[0].id, created: false };
      }
    }
    const id = randomUUID();
    await client.query(
      `INSERT INTO ops_items (id, rider_id, item_type, amount_rupees, reason, status, claim, claim_fingerprint)
       VALUES ($1, $2, $3, $4, $5, 'pending', $6::jsonb, $7)`,
      [id, args.riderId, args.type, args.amount, args.reason, JSON.stringify(args.claim), args.fingerprint],
    );
    await client.query("COMMIT");
    return { id, created: true };
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally {
    client.release();
  }
}

async function hasPriorClaim(pool: Pool, riderId: string, fingerprint: string): Promise<boolean> {
  const result = await pool.query<{ found: boolean }>(
    `SELECT EXISTS (
       SELECT 1 FROM payment_records
       WHERE rider_id = $1 AND claim_fingerprint = $2
         AND lower(status) IN ('reserved', 'processing', 'succeeded', 'paid', 'completed')
       UNION ALL
       SELECT 1 FROM ops_items
       WHERE rider_id = $1 AND claim_fingerprint = $2
         AND item_type = 'approval' AND status IN ('pending', 'approved', 'resolved')
     ) AS found`,
    [riderId, fingerprint],
  );
  return result.rows[0]?.found ?? false;
}

async function successfulPaymentForClaim(pool: Pool, riderId: string, fingerprint: string): Promise<{ payout_id: string | null; amount: number } | null> {
  const result = await pool.query<{ payout_id: string | null; amount: number }>(
    `SELECT payswift_payout_id AS payout_id, amount_rupees AS amount
     FROM payment_records WHERE rider_id = $1 AND claim_fingerprint = $2
       AND lower(status) = ANY($3::text[]) ORDER BY created_at DESC LIMIT 1`,
    [riderId, fingerprint, SUCCEEDED_PAYMENT_STATUSES],
  );
  return result.rows[0] ?? null;
}

async function recordClaimOccurrence(
  pool: Pool,
  riderId: string,
  fingerprint: string,
  messageId: string,
  claim: Record<string, unknown>,
): Promise<number> {
  const result = await pool.query<{ occurrence_count: number }>(
    `INSERT INTO claim_decisions (rider_id, claim_fingerprint, occurrence_count, last_message_id, latest_decision)
     VALUES ($1, $2, 1, $3, $4::jsonb)
     ON CONFLICT (rider_id, claim_fingerprint) DO UPDATE
       SET occurrence_count = claim_decisions.occurrence_count +
             CASE WHEN claim_decisions.last_message_id IS DISTINCT FROM EXCLUDED.last_message_id THEN 1 ELSE 0 END,
           last_message_id = EXCLUDED.last_message_id,
           latest_decision = EXCLUDED.latest_decision,
           last_seen_at = now()
     RETURNING occurrence_count`,
    [riderId, fingerprint, messageId, JSON.stringify(claim)],
  );
  return Number(result.rows[0]?.occurrence_count ?? 1);
}

async function updateClaimDecision(
  pool: Pool,
  riderId: string,
  fingerprint: string,
  claim: Record<string, unknown>,
): Promise<void> {
  await pool.query(
    `UPDATE claim_decisions
     SET latest_decision = $3::jsonb, last_seen_at = now()
     WHERE rider_id = $1 AND claim_fingerprint = $2`,
    [riderId, fingerprint, JSON.stringify(claim)],
  );
}

async function hasPaymentOnIstDate(pool: Pool, riderId: string, date: string): Promise<boolean> {
  const result = await pool.query<{ found: boolean }>(
    `SELECT EXISTS (
       SELECT 1 FROM payment_records
       WHERE rider_id = $1
         AND (created_at AT TIME ZONE 'Asia/Kolkata')::date = $2::date
         AND lower(status) = ANY($3::text[])
     ) AS found`,
    [riderId, date, ACTIVE_PAYMENT_STATUSES],
  );
  return result.rows[0]?.found ?? false;
}

async function hasOtherActiveSlot(pool: Pool, riderId: string, date: string, fingerprint: string): Promise<boolean> {
  const result = await pool.query<{ found: boolean }>(
    `SELECT EXISTS (
       SELECT 1 FROM automatic_payment_slots
       WHERE rider_id = $1 AND payout_date = $2::date
         AND claim_fingerprint <> $3 AND status IN ('reserved', 'consumed')
     ) AS found`,
    [riderId, date, fingerprint],
  );
  return result.rows[0]?.found ?? false;
}

async function reserveAutomaticSlot(
  pool: Pool,
  riderId: string,
  date: string,
  fingerprint: string,
  amount: number,
): Promise<boolean> {
  const result = await pool.query<{ claim_fingerprint: string }>(
    `INSERT INTO automatic_payment_slots (rider_id, payout_date, claim_fingerprint, amount_rupees, status)
     VALUES ($1, $2::date, $3, $4, 'reserved')
     ON CONFLICT (rider_id, payout_date) DO UPDATE
       SET claim_fingerprint = EXCLUDED.claim_fingerprint,
           amount_rupees = EXCLUDED.amount_rupees,
           status = 'reserved',
           created_at = now()
       WHERE automatic_payment_slots.status = 'released'
          OR automatic_payment_slots.claim_fingerprint = EXCLUDED.claim_fingerprint
     RETURNING claim_fingerprint`,
    [riderId, date, fingerprint, amount],
  );
  return result.rows[0]?.claim_fingerprint === fingerprint;
}

export async function decideClaimPaths(
  pool: Pool,
  riderId: string,
  outcomes: ClaimOutcome[],
  args: { messageId: string; identityMismatch: boolean; paymentProviderAvailable?: boolean },
): Promise<DecisionResult> {
  const events: DecisionEvent[] = [];
  if (args.identityMismatch) {
    const incidentFingerprint = createHash("sha256").update(`${riderId}:identity-mismatch:${args.messageId}`).digest("hex");
    const reason = "The message references a different rider identity; payout details were not checked.";
    const claim = {
      issue_id: null,
      fingerprint: incidentFingerprint,
      scope: null,
      status: "suspicious",
      decision_path: "suspicious_escalation",
      decision_reason: reason,
      verified_owed_rupees: 0,
      assessments: [],
      evidence: { identity_mismatch: true, message_id: args.messageId },
    };
    const opsItem = await createPendingOpsItem(pool, {
      riderId,
      type: "escalation",
      amount: null,
      reason,
      fingerprint: incidentFingerprint,
      claim,
    });
    events.push({
      type: "decision",
      name: "suspicious_claim_escalated",
      input: { message_id: args.messageId, rider_id: riderId },
      output: { ops_item_id: opsItem.id, created: opsItem.created, reason, verified_owed_rupees: 0 },
    });
    return {
      outcomes,
      events,
      identityMismatchReply: "I can help only with the rider account linked to this number. I have sent this identity mismatch to the operations team for review.",
    };
  }

  // This cap follows the actual processing/payment day, not a rider-supplied or backdated received_at.
  const paymentIstDate = istDate(new Date());
  const paymentAlreadyMadeToday = await hasPaymentOnIstDate(pool, riderId, paymentIstDate);
  const decided: ClaimOutcome[] = [];

  for (const source of outcomes) {
    const item: ClaimOutcome = { ...source };
    const fullyAssessed = item.status === "verified_shortfall" || item.status === "no_shortfall";
    const verifiedOwed = fullyAssessed
      ? Math.max(0, item.assessments.reduce((sum, assessment) => sum + assessment.shortfallRupees, 0))
      : 0;
    item.verified_owed_rupees = verifiedOwed;
    const fingerprint = fingerprintFor(riderId, item);
    item.claim_fingerprint = fingerprint;
    const occurrenceCount = item.status === "needs_information" || item.status === "unclear" || item.status === "suspicious"
      ? 0
      : await recordClaimOccurrence(pool, riderId, fingerprint, args.messageId, claimEvidence(item, fingerprint));

    if (item.status === "needs_information") {
      item.decision_path = "needs_information";
      item.decision_reason = "Required claim details are missing.";
    } else if (item.status === "suspicious") {
      item.decision_path = "suspicious_escalation";
      item.decision_reason = item.reason;
      const opsItem = await createPendingOpsItem(pool, {
        riderId, type: "escalation", amount: null, reason: `Possible account or trip ownership mismatch: ${item.reason}`,
        fingerprint, claim: claimEvidence(item, fingerprint),
      });
      item.ops_item_id = opsItem.id;
      item.reply = "The trip details do not match the rider account linked to this number. I have sent the case to the operations team to review.";
    } else if (item.status === "unclear") {
      item.decision_path = "unclear_escalation";
      item.decision_reason = item.reason;
      const opsItem = await createPendingOpsItem(pool, {
        riderId, type: "escalation", amount: null, reason: `Claim could not be verified: ${item.reason}`,
        fingerprint, claim: claimEvidence(item, fingerprint),
      });
      item.ops_item_id = opsItem.id;
      item.reply = `I could not verify this claim from the available records: ${item.reason}. I have sent it to the operations team for review.`;
    } else if (verifiedOwed === 0) {
      item.decision_path = "no_payment_due";
      item.decision_reason = "The checked policy and payout records show no positive shortfall.";
    } else if ((occurrenceCount > 1 || await hasPriorClaim(pool, riderId, fingerprint)) && await successfulPaymentForClaim(pool, riderId, fingerprint)) {
      const priorPayment = await successfulPaymentForClaim(pool, riderId, fingerprint);
      item.decision_path = "repeat_already_paid_escalation";
      item.decision_reason = "PaySwift already records a completed payment for this exact claim; a repeat report is sent to operations without creating another payable approval.";
      const opsItem = await createPendingOpsItem(pool, {
        riderId, type: "escalation", amount: null,
        reason: `${item.decision_reason} Existing payout ID: ${priorPayment?.payout_id ?? "not supplied by PaySwift"}; amount: ₹${priorPayment?.amount ?? 0}.`,
        fingerprint, claim: claimEvidence(item, fingerprint),
      });
      item.ops_item_id = opsItem.id;
      item.reply = `PaySwift records a ₹${priorPayment?.amount ?? 0} payment for this claim${priorPayment?.payout_id ? ` (payout ${priorPayment.payout_id})` : ""}. Since this is a repeat report, I have sent it to operations to review; I have not sent another payment.`;
    } else if (occurrenceCount > 1 || await hasPriorClaim(pool, riderId, fingerprint)) {
      item.decision_path = "repeat_claim_approval";
      item.decision_reason = "A prior approved or active payment record matches this rider, trip/date, and claim.";
      item.decision_amount_rupees = verifiedOwed;
      const opsItem = await createPendingOpsItem(pool, {
        riderId, type: "approval", amount: verifiedOwed,
        reason: `Repeat claim requires manual review; verified amount is ₹${verifiedOwed}.`,
        fingerprint, claim: claimEvidence(item, fingerprint),
      });
      item.ops_item_id = opsItem.id;
      item.reply = `The verified shortfall is ₹${verifiedOwed}. This matches a prior claim, so I have sent it for operations approval before any payment.`;
    } else if (verifiedOwed > AUTO_PAYMENT_CAP_RUPEES) {
      item.decision_path = "large_claim_approval";
      item.decision_reason = `Verified amount ₹${verifiedOwed} is above the ₹${AUTO_PAYMENT_CAP_RUPEES} automatic-payment limit per dispute.`;
      item.decision_amount_rupees = verifiedOwed;
      const opsItem = await createPendingOpsItem(pool, {
        riderId, type: "approval", amount: verifiedOwed,
        reason: item.decision_reason,
        fingerprint, claim: claimEvidence(item, fingerprint),
      });
      item.ops_item_id = opsItem.id;
      item.reply = `I verified a shortfall of ₹${verifiedOwed}. This is above the ₹${AUTO_PAYMENT_CAP_RUPEES} automatic limit, so I have sent it to operations for approval. No payment has been made.`;
    } else if (args.paymentProviderAvailable === false) {
      item.decision_path = "payment_provider_unavailable";
      item.decision_reason = "PaySwift ledger could not be reconciled, so automatic payment was not attempted.";
      item.decision_amount_rupees = verifiedOwed;
      const opsItem = await createPendingOpsItem(pool, {
        riderId, type: "approval", amount: verifiedOwed,
        reason: `${item.decision_reason} Verified shortfall: ₹${verifiedOwed}.`,
        fingerprint, claim: claimEvidence(item, fingerprint),
      });
      item.ops_item_id = opsItem.id;
      item.reply = `I verified a shortfall of ₹${verifiedOwed}, but I could not confirm the PaySwift ledger. I have sent it to operations for review; no payment was made.`;
    } else if (paymentAlreadyMadeToday || await hasOtherActiveSlot(pool, riderId, paymentIstDate, fingerprint)) {
      item.decision_path = "daily_limit_approval";
      item.decision_reason = `The one automatic payment per rider per IST day limit has already been used or reserved on ${paymentIstDate}.`;
      item.decision_amount_rupees = verifiedOwed;
      const opsItem = await createPendingOpsItem(pool, {
        riderId, type: "approval", amount: verifiedOwed,
        reason: `Daily automatic-payment limit used or reserved on ${paymentIstDate}; verified amount is ₹${verifiedOwed}.`,
        fingerprint, claim: claimEvidence(item, fingerprint),
      });
      item.ops_item_id = opsItem.id;
      item.reply = `I verified a shortfall of ₹${verifiedOwed}, but the one automatic payment allowed for your account on ${paymentIstDate} has already been used or reserved. I have sent this claim to operations for approval. No payment has been made.`;
    } else {
      // Reserve the single daily slot before the PaySwift request is made.
      const autoAmount = Math.min(verifiedOwed, AUTO_PAYMENT_CAP_RUPEES);
      const reserved = await reserveAutomaticSlot(pool, riderId, paymentIstDate, fingerprint, autoAmount);
      if (!reserved) {
        item.decision_path = "daily_limit_approval";
        item.decision_reason = `Another claim already reserved the one automatic payment slot for ${paymentIstDate}.`;
        item.decision_amount_rupees = verifiedOwed;
        const opsItem = await createPendingOpsItem(pool, {
          riderId, type: "approval", amount: verifiedOwed,
          reason: `Daily automatic-payment limit reserved on ${paymentIstDate}; verified amount is ₹${verifiedOwed}.`,
          fingerprint, claim: claimEvidence(item, fingerprint),
        });
        item.ops_item_id = opsItem.id;
        item.reply = `I verified a shortfall of ₹${verifiedOwed}, but your automatic-payment slot for ${paymentIstDate} is already reserved. I have sent this claim to operations for approval. No payment has been made.`;
      } else {
        item.decision_path = "auto_payment_eligible";
        item.decision_reason = `Verified amount is within the ₹${AUTO_PAYMENT_CAP_RUPEES} per-dispute limit and this claim reserved the rider's one automatic-payment slot for ${paymentIstDate}.`;
        item.decision_amount_rupees = autoAmount;
        item.reply = `I verified a shortfall of ₹${autoAmount}. It is within the automatic-payment limits and reserved for processing, but no payment was made in this step.`;
      }
    }

    events.push({
      type: "decision",
      name: "claim_payment_path_selected",
      input: { issue_id: item.issue_id, rider_id: riderId, scope: item.scope, fingerprint },
      output: {
        path: item.decision_path,
        reason: item.decision_reason,
        payment_ist_date: paymentIstDate,
        verified_owed_rupees: verifiedOwed,
        amount_never_exceeds_verified_owed: (item.decision_amount_rupees ?? 0) <= verifiedOwed,
        per_dispute_cap_rupees: AUTO_PAYMENT_CAP_RUPEES,
        daily_ist_limit: 1,
        ops_item_id: item.ops_item_id ?? null,
      },
    });
    if (occurrenceCount > 0) {
      await updateClaimDecision(pool, riderId, fingerprint, claimEvidence(item, fingerprint));
    }
    decided.push(item);
  }
  return { outcomes: decided, events };
}
import { Pool } from "pg";
import {
  assessDay,
  assessTrip,
  disputeIsInWindow,
  istDate,
  PayoutAssessment,
  PayoutLine,
  TripRecord,
} from "../domain/payouts.js";
import { IssueUpdate } from "../infrastructure/llm/groq-client.js";

export type ClaimStatus = "needs_information" | "verified_shortfall" | "no_shortfall" | "unclear" | "suspicious";

export interface InvestigationTarget {
  issueId: string;
  update: IssueUpdate;
}

export interface InvestigationEvent {
  type: "tool_call" | "decision" | "error";
  name: string;
  input: unknown;
  output: unknown;
}

export interface ClaimOutcome {
  issue_id: string;
  status: ClaimStatus;
  scope: "trip" | "day" | null;
  reason: string;
  assessments: PayoutAssessment[];
  decision_path?: "needs_information" | "unclear_escalation" | "suspicious_escalation" | "large_claim_approval" | "repeat_claim_approval" | "repeat_already_paid_escalation" | "daily_limit_approval" | "payment_provider_unavailable" | "payment_guard_rejected" | "auto_payment_eligible" | "payment_succeeded" | "payment_result_uncertain" | "payment_failed_review" | "no_payment_due";
  decision_reason?: string;
  verified_owed_rupees?: number;
  decision_amount_rupees?: number | null;
  ops_item_id?: string | null;
  claim_fingerprint?: string;
  reply: string;
}

export interface InvestigationResult {
  outcomes: ClaimOutcome[];
  events: InvestigationEvent[];
}

interface DbTrip {
  trip_id: string;
  rider_id: string;
  started_at: Date;
  status: TripRecord["status"];
  distance_km: string;
  surge_multiplier: string;
}

interface DbPayoutLine {
  line_id: string;
  payout_date: string;
  rider_id: string;
  line_type: string;
  trip_id: string | null;
  amount_rupees: number;
}

function canonicalRiderId(value: string): string {
  const match = /^R(\d+)$/i.exec(value.trim());
  return match ? `R${Number(match[1]).toString().padStart(3, "0")}` : value.trim().toUpperCase();
}

function toTrip(row: DbTrip): TripRecord {
  return {
    tripId: row.trip_id,
    riderId: row.rider_id,
    startedAt: row.started_at,
    status: row.status,
    distanceKm: row.distance_km,
    surgeMultiplier: row.surge_multiplier,
  };
}

function toPayoutLine(row: DbPayoutLine): PayoutLine {
  return {
    lineId: row.line_id,
    payoutDate: row.payout_date,
    riderId: row.rider_id,
    lineType: row.line_type,
    tripId: row.trip_id,
    amountRupees: Number(row.amount_rupees),
  };
}

function resultStatus(shortfall: number): ClaimStatus {
  return shortfall > 0 ? "verified_shortfall" : "no_shortfall";
}

function resultReply(status: ClaimStatus, assessments: PayoutAssessment[], reason: string): string {
  if (status === "needs_information") {
    return reason === "date"
      ? "Could you share the trip ID or the date of the payout you want checked?"
      : "Could you share the trip ID related to the payout issue?";
  }
  if (status === "unclear") {
    return `I could not verify this claim from the available records: ${reason}. I have sent it to the operations team for review.`;
  }
  if (status === "suspicious") {
    return `The trip details do not match the rider account linked to this number. I have sent the case to the operations team to review.`;
  }

  const totalExpected = assessments.reduce((sum, item) => sum + item.expectedRupees, 0);
  const totalPaid = assessments.reduce((sum, item) => sum + item.historicalPaidRupees, 0);
  const shortfall = totalExpected - totalPaid;
  const dates = [...new Set(assessments.map((item) => item.payoutDate))];
  const dateLabel = dates.length === 1 ? dates[0] : dates.join(", ");
  const dayTripIds = assessments.flatMap((assessment) =>
    assessment.tripId ? [assessment.tripId] : assessment.breakdown.flatMap((line) => line.match(/\bT[A-Z0-9_-]{2,40}\b/g) ?? []));
  const uniqueDayTripIds = [...new Set(dayTripIds)];
  const tripContext = uniqueDayTripIds.length
    ? ` (including trip${uniqueDayTripIds.length === 1 ? "" : "s"} ${uniqueDayTripIds.slice(0, 5).join(", ")}${uniqueDayTripIds.length > 5 ? ` and ${uniqueDayTripIds.length - 5} more` : ""})`
    : "";
  const checkedRecords = `the ${assessments.length === 1 && assessments[0]!.scope === "trip" ? `trip ${assessments[0]!.tripId}` : `payout records${tripContext}`} for ${dateLabel}`;
  if (status === "verified_shortfall") {
    return `I checked ${checkedRecords}. Policy amount: ₹${totalExpected}; recorded payout: ₹${totalPaid}; verified shortfall: ₹${shortfall}. No payment was made in this step.`;
  }
  return `I checked ${checkedRecords}. Policy amount: ₹${totalExpected}; recorded payout: ₹${totalPaid}. The records show no additional amount is due.`;
}

function outcome(
  issueId: string,
  status: ClaimStatus,
  scope: ClaimOutcome["scope"],
  reason: string,
  assessments: PayoutAssessment[] = [],
): ClaimOutcome {
  return {
    issue_id: issueId,
    status,
    scope,
    reason,
    assessments,
    reply: resultReply(status, assessments, reason),
  };
}

export async function investigateIssues(
  pool: Pool,
  riderId: string,
  receivedAt: Date,
  targets: InvestigationTarget[],
): Promise<InvestigationResult> {
  if (targets.length === 0) return { outcomes: [], events: [] };
  const events: InvestigationEvent[] = [];
  const lookupRiderId = canonicalRiderId(riderId);
  const rider = await pool.query<{ rider_id: string }>(
    "SELECT rider_id FROM riders WHERE rider_id = $1",
    [lookupRiderId],
  );
  events.push({
    type: "tool_call",
    name: "rider_record_lookup",
    input: { requested_rider_id: riderId, normalized_rider_id: lookupRiderId },
    output: { found: rider.rowCount === 1, rider_id: rider.rows[0]?.rider_id ?? null },
  });

  if (!rider.rows[0]) {
    const outcomes = targets.map(({ issueId }) => outcome(issueId, "unclear", null, "the rider account was not found"));
    for (const item of outcomes) events.push({ type: "decision", name: "claim_not_verifiable", input: { issue_id: item.issue_id }, output: item });
    return { outcomes, events };
  }

  const canonicalId = rider.rows[0].rider_id;
  const outcomes: ClaimOutcome[] = [];
  for (const target of targets) {
    const { issueId, update } = target;
    if (update.missing_information.includes("issue_details") && update.trip_ids.length === 0 && update.dates.length === 0) {
      outcomes.push(outcome(issueId, "needs_information", null, "issue_details"));
      continue;
    }

    if (update.trip_ids.length > 0) {
      const assessments: PayoutAssessment[] = [];
      let unclearReason: string | null = null;
      for (const tripId of [...new Set(update.trip_ids)]) {
        const tripResult = await pool.query<DbTrip>(
          `SELECT trip_id, rider_id, started_at, status,
                  distance_km::text AS distance_km, surge_multiplier::text AS surge_multiplier
           FROM trips WHERE trip_id = $1`,
          [tripId],
        );
        const row = tripResult.rows[0];
        events.push({
          type: "tool_call",
          name: "trip_record_lookup",
          input: { issue_id: issueId, trip_id: tripId },
          output: row ? { found: true, rider_id: row.rider_id, payout_date: istDate(row.started_at), status: row.status } : { found: false },
        });
        if (!row) {
          unclearReason = `trip ${tripId} was not found`;
          break;
        }
        if (row.rider_id !== canonicalId) {
          unclearReason = `trip ${tripId} is not linked to this rider account`;
          break;
        }
        const trip = toTrip(row);
        const tripDate = istDate(trip.startedAt);
        if (update.dates.length > 0 && !update.dates.includes(tripDate)) {
          unclearReason = `trip ${tripId} does not match the date provided`;
          break;
        }
        if (!disputeIsInWindow(tripDate, receivedAt)) {
          unclearReason = `trip ${tripId} is outside the seven-day review window`;
          break;
        }
        const linesResult = await pool.query<DbPayoutLine>(
          `SELECT line_id, payout_date::text AS payout_date, rider_id, line_type,
                  trip_id, amount_rupees
           FROM payout_lines WHERE rider_id = $1 AND trip_id = $2 ORDER BY line_id`,
          [canonicalId, tripId],
        );
        const lines = linesResult.rows.map(toPayoutLine);
        events.push({
          type: "tool_call",
          name: "trip_payout_lookup",
          input: { issue_id: issueId, rider_id: canonicalId, trip_id: tripId },
          output: { line_count: lines.length, lines },
        });
        assessments.push(assessTrip(trip, lines));
      }
      if (unclearReason) {
        const suspicious = unclearReason.includes("not linked to this rider account");
        outcomes.push(outcome(issueId, suspicious ? "suspicious" : "unclear", "trip", unclearReason, assessments));
        continue;
      }
      const totalShortfall = assessments.reduce((sum, assessment) => sum + assessment.shortfallRupees, 0);
      const status = resultStatus(totalShortfall);
      outcomes.push(outcome(issueId, status, "trip", "trip records and policy were checked", assessments));
      continue;
    }

    const dates = [...new Set(update.dates)];
    if (dates.length === 0) {
      outcomes.push(outcome(issueId, "needs_information", null, "date"));
      continue;
    }

    const assessments: PayoutAssessment[] = [];
    let unclearReason: string | null = null;
    for (const date of dates) {
      if (!disputeIsInWindow(date, receivedAt)) {
        unclearReason = `${date} is outside the seven-day review window`;
        break;
      }
      const dayTripsResult = await pool.query<DbTrip>(
        `SELECT trip_id, rider_id, started_at, status,
                distance_km::text AS distance_km, surge_multiplier::text AS surge_multiplier
         FROM trips
         WHERE rider_id = $1 AND (started_at AT TIME ZONE 'Asia/Kolkata')::date = $2::date
         ORDER BY started_at, trip_id`,
        [canonicalId, date],
      );
      const trips = dayTripsResult.rows.map(toTrip);
      events.push({
        type: "tool_call",
        name: "day_trip_lookup",
        input: { issue_id: issueId, rider_id: canonicalId, payout_date: date },
        output: { trip_count: trips.length, trip_ids: trips.map((trip) => trip.tripId) },
      });
      if (trips.length === 0) {
        unclearReason = `no trip records were found for ${date}`;
        break;
      }
      const dayLinesResult = await pool.query<DbPayoutLine>(
        `SELECT line_id, payout_date::text AS payout_date, rider_id, line_type,
                trip_id, amount_rupees
         FROM payout_lines WHERE rider_id = $1 AND payout_date = $2::date ORDER BY line_id`,
        [canonicalId, date],
      );
      const lines = dayLinesResult.rows.map(toPayoutLine);
      events.push({
        type: "tool_call",

